const doc = $.steps.createDoc.response || {};
const docUrl = doc.documentId ? `https://docs.google.com/document/d/${doc.documentId}/edit` : '';
return {
  documentId: doc.documentId || '',
  title: doc.title || $.input.title,
  url: docUrl,
  created: !!doc.documentId,
  hasContent: !!$.input.content,
  summary: doc.documentId ? `Created document "${doc.title || $.input.title}"` : 'Failed to create document'
};
